INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z15-q16','nism-5b-z15','NAV of close-ended schemes must be disclosed at least:','["Once a week","Quarterly","Daily","Monthly"]',0,'Per disclosure norms.',16) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z15-q17','nism-5b-z15','Commercial Paper (CP) is issued by:','["Banks for 7 days","Government","RBI","Companies for up to 1 year"]',3,'Certificates of Deposit are issued by banks (7 days–1 year) and FIs (1–3 years).',17) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z15-q18','nism-5b-z15','Index funds and ETFs have:','["Two benchmarks","A single benchmark, which is the replicated index","A gold benchmark","No benchmark"]',1,'Thematic and sectoral also have a single benchmark.',18) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z15-q19','nism-5b-z15','An investor sells equity-oriented fund units after 18 months with a long-term capital gain of ₹5,15,000 (no other LTCG in the year). As per the rates in the current workbook, the LTCG tax (ignoring cess) is:','["₹48,750","₹78,000","₹64,375","₹1,03,000"]',0,'Taxable = 515000 − 1,25,000; tax at 12.5% = ₹48,750.',19) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z15-q20','nism-5b-z15','The Instant Access Facility for liquid and overnight funds credits the lower of:','["₹1 lakh or 50% of the value","₹10,000 or 100% of value","₹5 lakh or 80% of value","₹50,000 or 90% of the value, per day per scheme"]',3,'It gives same-day credit.',20) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z15-q21','nism-5b-z15','A hybrid scheme''s benchmark is typically:','["A single bond index","Gold price","The Nifty only","A blended index such as 65% Sensex + 35% I-Bex"]',3,'It reflects the scheme''s asset mix.',21) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z15-q22','nism-5b-z15','An investment of ₹79,000 grows to ₹1,05,720 in 5 years. The compounded annual growth rate (CAGR) is closest to:','["6.0%","8.0%","6.8%","4.0%"]',0,'CAGR = (end/start)^(1/5) − 1 ≈ 6%.',22) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z15-q23','nism-5b-z15','The sponsor''s liability for a mutual fund scheme is:','["Zero and no contribution is made","Unlimited","Equal to total corpus","Limited to its initial contribution"]',3,'This is a standard risk statement.',23) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z15-q24','nism-5b-z15','A scheme has an NAV of ₹58.70 and an exit load of 0.5%. The redemption (repurchase) price per unit is:','["₹58.99","₹58.20","₹58.70","₹58.41"]',3,'Repurchase price = 58.70 × (1 − 0.5%) = ₹58.41.',24) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z15-q25','nism-5b-z15','A distributor has ₹23,00,000 of client AUM in regular plans with a trail rate of 1.25% p.a. The approximate daily trail commission is:','["₹2,395.83","₹945.21","₹78.77","₹2,363.01"]',2,'Daily trail = AUM × rate ÷ 365 = ₹78.77.',25) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
