INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q15','nism-5b-z20','A refund after an NFO delayed beyond 5 business days attracts interest at:','["10% p.a. borne by the investor","5% p.a. charged to the scheme","12% p.a. charged to the scheme","15% p.a. borne by the AMC"]',3,'It is not chargeable to the scheme.',15) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q16','nism-5b-z20','In-Person Verification (IPV) for KYC can be done by:','["Only AMFI","Only the AMC","Only SEBI","The intermediary or a scheduled commercial bank"]',3,'IPV is mandatory.',16) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q17','nism-5b-z20','An investor sells equity-oriented fund units after 18 months with a long-term capital gain of ₹2,45,000 (no other LTCG in the year). As per the rates in the current workbook, the LTCG tax (ignoring cess) is:','["₹15,000","₹49,000","₹30,625","₹24,000"]',0,'Taxable = 245000 − 1,25,000; tax at 12.5% = ₹15,000.',17) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q18','nism-5b-z20','An investor sells equity-oriented fund units after 18 months with a long-term capital gain of ₹2,85,000 (no other LTCG in the year). As per the rates in the current workbook, the LTCG tax (ignoring cess) is:','["₹32,000","₹35,625","₹57,000","₹20,000"]',3,'Taxable = 285000 − 1,25,000; tax at 12.5% = ₹20,000.',18) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q19','nism-5b-z20','A fund returned 18% with a standard deviation of 15%. The risk-free rate is 7%. The Sharpe ratio is:','["0.73","0.65","1.67","1.20"]',0,'Sharpe = (18 − 7) ÷ 15.',19) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q20','nism-5b-z20','For liquid and overnight schemes, the cut-off time for purchases is:','["1:30 pm","2:30 pm","3:00 pm","12:00 noon"]',0,'Funds must be available before the cut-off to get the NAV of the day before receipt.',20) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q21','nism-5b-z20','In the IDCW Payout option, NAV after the payout:','["Falls by the IDCW","Rises","Equals face value","Stays unchanged"]',0,'In Growth, NAV reflects the full gains.',21) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q22','nism-5b-z20','An investment of ₹76,000 grows to ₹1,18,628 in 3 years. The compounded annual growth rate (CAGR) is closest to:','["18.7%","16.0%","14.0%","18.0%"]',1,'CAGR = (end/start)^(1/3) − 1 ≈ 16%.',22) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q23','nism-5b-z20','The risk-free return used in the Sharpe ratio is usually based on:','["A corporate bond index","The gold price","The sensex","The T-Bill index"]',3,'Rf is the risk-free return.',23) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q24','nism-5b-z20','A scheme has an NAV of ₹35.10 and an exit load of 2%. The redemption (repurchase) price per unit is:','["₹35.80","₹35.10","₹33.10","₹34.40"]',3,'Repurchase price = 35.10 × (1 − 2%) = ₹34.40.',24) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q25','nism-5b-z20','The fund factsheet is:','["Mandatory by law","Prepared by SEBI","Monthly and non-mandatory (AMFI best practice)","Issued daily"]',2,'SEBI disclosure rules still apply.',25) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q26','nism-5b-z20','Real return is:','["Nominal return adjusted for inflation","Return net of tax only","Return on a real-estate investment","Return before expenses"]',0,'FD 7% with 8% inflation gives a negative real return.',26) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
