INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q32','nism-5b-z20','The I-Bex sub-indices Si-Bex, Mi-Bex and Li-Bex refer to maturities of:','["Up to 1 year, 1–5 years and 5–10 years","0–91 days, 91–365 days and above","1–3 years, 3–7 years and over 7 years","1–2, 2–4 and 4–6 years"]',2,'They are ICICI Securities indices.',32) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
