INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q34','nism-5b-z20','"Risk capacity" of an investor refers to:','["Risk rating of the scheme","Psychological willingness to take risk","Financial ability and investment horizon","Risk needed to reach goals"]',2,'Risk tolerance is psychological; risk capacity is financial ability and horizon.',34) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
