INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q36','nism-5b-z20','In an SIP, rupee cost averaging means that over time:','["The average cost per unit tends to be lower than the average NAV","NAV never falls","No tax is payable","Returns are guaranteed"]',0,'In the deck example, average cost ₹10.55 against average NAV ₹10.67.',36) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
