INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q57','nism-5b-z20','A fund returned 11% with a standard deviation of 17%. The risk-free rate is 6%. The Sharpe ratio is:','["1.00","0.26","0.65","0.29"]',3,'Sharpe = (11 − 6) ÷ 17.',57) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q58','nism-5b-z20','An investor sells equity-oriented fund units after 18 months with a long-term capital gain of ₹6,75,000 (no other LTCG in the year). As per the rates in the current workbook, the LTCG tax (ignoring cess) is:','["₹1,10,000","₹84,375","₹68,750","₹1,35,000"]',2,'Taxable = 675000 − 1,25,000; tax at 12.5% = ₹68,750.',58) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q59','nism-5b-z20','A scheme with average net assets of ₹4700 crore incurs total recurring expenses of ₹1.00 crore in a year. Its expense ratio is:','["0.011%","0.032%","0.043%","0.021%"]',3,'TER = 1.00 ÷ 4700 × 100 = 0.021%.',59) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q60','nism-5b-z20','Daily trail commission is calculated as:','["AUM × trail rate p.a. ÷ 365","NAV × units","Units × face value","AUM × trail rate ÷ 12 ÷ 100"]',0,'Paid monthly or quarterly.',60) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q61','nism-5b-z20','GST on distributor commission is payable when annual turnover exceeds:','["₹40 lakh","₹10 lakh","₹1 crore","₹20 lakh"]',3,'Reverse charge applies to unregistered suppliers.',61) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q62','nism-5b-z20','Weekly standard deviation is annualised by multiplying by:','["√252","√52","√12","52"]',1,'Monthly × √12; daily × √252.',62) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q63','nism-5b-z20','With a scheme return of 8%, risk-free 5% and beta 1.2, the Treynor ratio is:','["1.5","2.5","3.0","0.6"]',1,'(8 − 5) ÷ 1.2 = 2.5.',63) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q64','nism-5b-z20','Information Ratio equals:','["Alpha ÷ beta","(Portfolio return − benchmark return) ÷ standard deviation of excess return","Return ÷ expenses","Return ÷ beta"]',1,'The denominator is the tracking error.',64) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q65','nism-5b-z20','An investor holds 280 units under the IDCW Reinvestment option. IDCW is ₹1 per unit and the ex-IDCW NAV is ₹20. The additional units allotted are:','["13.33","280.00","14.00","28.00"]',2,'Units = (280 × 1) ÷ 20 = 14.00.',65) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q66','nism-5b-z20','An investor redeems 690 units at an NAV of ₹45.90 with an exit load of 1%. The amount received (before tax) is:','["₹31,671.00","₹30,981.00","₹31,987.71","₹31,354.29"]',3,'690 × 45.90 × 0.99.',66) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q67','nism-5b-z20','For an interval fund, the minimum transaction period and interval period are respectively:','["3 days and 60 days","2 days and 15 calendar days","1 day and 7 days","5 days and 30 days"]',1,'Transaction period at least 2 days; interval period at least 15 calendar days.',67) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q68','nism-5b-z20','A distributor has ₹42,00,000 of client AUM in regular plans with a trail rate of 0.5% p.a. The approximate daily trail commission is:','["₹1,726.03","₹57.53","₹690.41","₹1,750.00"]',1,'Daily trail = AUM × rate ÷ 365 = ₹57.53.',68) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q69','nism-5b-z20','A SIP Top-up of +10% a year on ₹2,500 gives an instalment in year 2 of:','["₹3,000","₹2,600","₹2,750","₹2,510"]',2,'2,500 × 1.10 = 2,750.',69) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q70','nism-5b-z20','An investor sells equity-oriented fund units after 18 months with a long-term capital gain of ₹2,65,000 (no other LTCG in the year). As per the rates in the current workbook, the LTCG tax (ignoring cess) is:','["₹17,500","₹33,125","₹28,000","₹53,000"]',0,'Taxable = 265000 − 1,25,000; tax at 12.5% = ₹17,500.',70) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q71','nism-5b-z20','Even during gating, the first ___ of each redemption request is paid.','["₹1 lakh","₹50,000","₹2 lakh","₹5 lakh"]',2,'The possibility of gating must be disclosed in scheme documents.',71) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q72','nism-5b-z20','A scheme has total assets of ₹299.60 crore, liabilities (other than to unitholders) of ₹3.20 crore and 2.80 crore units outstanding. Its NAV per unit is:','["₹105.86","₹78.00","₹107.00","₹108.14"]',0,'NAV = (299.60 − 3.20) ÷ 2.80 = ₹105.86.',72) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q73','nism-5b-z20','A goal costs ₹93,000 today. With inflation of 7% p.a., its cost after 11 years will be approximately:','["₹2,09,454","₹1,95,751","₹1,64,610","₹1,82,945"]',1,'FV = 93000 × (1 + 7%)^11.',73) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
